<template><section class="ur" :aria-label="$t(&quot;完整 UMI 记录&quot;)">
  <header><div><h2>{{adminView?$t('业务查询与完整导出'):$t('我的完整记录')}}</h2><p v-if="adminView">{{ $t("按业务时区 UTC+8 查询；汇总覆盖当前筛选范围的全部记录。") }}</p></div><a v-if="!adminView || allowExport" :href="exportUrl">{{ $t("导出当前范围 CSV") }}</a></header>
  <form class="ur-filters" @submit.prevent="load(1)">
    <label>{{ $t("记录类型") }}<select v-model="dataset" @change="changeDataset"><option v-for="(label,key) in datasets" :key="key" :value="key">{{ $t(label) }}</option></select></label>
    <label v-if="adminView && supportsMember">{{ $t("成员 ID") }}<input v-model.trim="memberId" @input="rootId=''" inputmode="numeric" :placeholder="$t(&quot;全部成员&quot;)"></label>
    <label v-if="adminView && supportsMember">{{ $t("伞下根成员 ID") }}<input v-model.trim="rootId" @input="memberId=''" inputmode="numeric" :placeholder="$t(&quot;含根成员及下级&quot;)"></label>
    <label v-if="dataset==='members'">{{ $t("成员搜索") }}<input v-model.trim="search" :placeholder="$t(&quot;邀请码 / 原 UID / Deepro ID&quot;)"></label>
    <label v-if="['withdrawals','lots','points'].includes(dataset)">{{ $t("提取订单 ID") }}<input v-model.trim="withdrawalId" inputmode="numeric" :placeholder="$t(&quot;全部订单&quot;)"></label><label>{{ $t("开始日期") }}<input type="date" v-model="from"></label><label>{{ $t("结束日期") }}<input type="date" v-model="to"></label>
    <label v-if="result?.options.status.length">{{ $t("状态") }}<select v-model="status"><option value="">{{ $t("全部") }}</option><option v-for="s in result.options.status" :key="s" :value="s">{{ $t(statusLabel(s)) }}</option></select></label>
    <label v-if="result?.options.source.length">{{ $t("来源 / 类别") }}<select v-model="source"><option value="">{{ $t("全部") }}</option><option v-for="s in result.options.source" :key="s" :value="s">{{ $t(statusLabel(s)) }}</option></select></label>
    <button :disabled="loading">{{ $t("查询") }}</button><button type="button" @click="reset">{{ $t("重置") }}</button>
  </form>
  <p v-if="loading" role="status">{{ $t("正在查询…") }}</p><p v-if="error" class="ur-error" role="alert">{{ $t(error) }} <button @click="load(page)">{{ $t("重试") }}</button></p>
  <template v-if="result && !loading && !error"><div class="ur-summary"><b>{{ $t("共") }} {{result.total}} {{ $t("条") }}</b><span v-for="(v,k) in result.totals" :key="k">{{ $t(label(k)) }}：{{fmt(v)}}</span></div>
    <p v-if="!result.rows.length">{{ $t("当前条件下暂无记录。") }}</p>
    <div v-else class="ur-scroll"><table><thead><tr><th v-for="c in visibleColumns" :key="c">{{ $t(label(c)) }}</th><th>{{ $t("详情") }}</th></tr></thead><tbody><template v-for="(row,index) in result.rows"><tr :key="'r'+index"><td v-for="c in visibleColumns" :key="c">{{display(row[c],c)}}</td><td><button @click="expanded=expanded===index?null:index">{{expanded===index?$t('收起'):$t('查看')}}</button><button v-if="adminView && dataset==='members'" @click="$emit('member',row.id)">{{ $t("用户全景") }}</button></td></tr><tr v-if="expanded===index" :key="'d'+index"><td :colspan="visibleColumns.length+1"><dl><template v-for="c in result.columns"><dt :key="c+'k'">{{ $t(label(c)) }}</dt><dd :key="c+'v'"><a v-if="c==='tx_hash' && /^0x[a-fA-F0-9]{64}$/.test(row[c]||'') && Number(row.chain_id)===56" :href="'https://bscscan.com/tx/'+row[c]" target="_blank" rel="noopener noreferrer">{{row[c]}}</a><span v-else>{{display(row[c],c)}}</span></dd></template></dl></td></tr></template></tbody></table></div>
    <footer><button :disabled="page<=1" @click="load(page-1)">{{ $t("上一页") }}</button><span>{{page}} / {{result.last_page}} {{ $t("页 · 每页 25 条") }}</span><button :disabled="page>=result.last_page" @click="load(page+1)">{{ $t("下一页") }}</button></footer>
    <small v-if="adminView">{{ $t("查询时间") }} {{time(result.queried_at)}}{{ $t("；CSV 附筛选范围、条数、汇总和校验值。") }}</small>
  </template>
</section></template>
<script>
import UmiLocale from '@/Functions/UmiLocale';
import axios from 'axios';
import {formatUmi,umiTime,umiStatus} from '@/Functions/UmiDisplay';
const names={wallet_moves:'账户划转凭证',intents:'充值订单',cycles:'充值轮次',releases:'收益明细',transfers:'收益划转',withdrawals:'提取到 Deepro',lots:'销毁任务',points:'股票积分',stock_moves:'股票份额流水',members:'成员目录',stock_accounts:'股票账户',quotes:'报价记录',daily:'日结记录',settings:'配置记录',activation:'原用户开通记录',recovery:'异常恢复任务',recovery_actions:'异常恢复操作',ranks:'等级变更记录'};
const labels={from_bucket:'转出账户类别',to_bucket:'转入账户类别',from_user_id:'转出用户',to_user_id:'转入用户',point_entry_id:'积分记录 ID',exchange_wallet_id:'Deepro 钱包 ID',exchange_balance_before:'交易账户划转前',exchange_balance_after:'交易账户划转后',id:'记录 ID',member_id:'成员 ID',user_id:'Deepro 用户 ID',member_code:'UMI 邀请码',legacy_identity_ref:'原身份索引',level:'等级',status:'状态',source:'来源',kind:'类别',pocket:'收益类别',purpose:'用途',amount_umi:'数量 UMI',principal_umi:'本金 UMI',principal_usd:'充值价值 USDT',multiplier:'倍率',cap_umi:'总额度 UMI',released_umi:'已释放 UMI',cycle_number:'轮次',cycle_id:'轮次 ID',withdrawal_id:'提取订单 ID',requested_umi:'申请到账 UMI',required_burn_umi:'所需销毁 UMI',confirmed_burn_umi:'已确认销毁 UMI',paid_umi:'已到账 UMI',paid_at:'到账时间',payout_ref:'到账凭证',created_at:'创建时间',joined_at:'加入时间',starts_on:'起算日',business_date:'业务日期',from_income_umi:'收益支付 UMI',from_wallet_umi:'账户划入 UMI',from_deposit_umi:'历史充值 UMI',remaining_umi:'补款缺口 UMI',delta_points:'积分',shares:'份额',term_status:'权益状态',eligible_at:'预计确权时间',unlock_at:'预计解锁时间',confirmed_at:'确认时间',tradable_at:'实际解锁时间',tx_hash:'链上交易哈希',chain_id:'链 ID',finalized_at:'链上最终确认时间',policy_version_id:'规则版本',from_member_id:'转出成员',to_member_id:'转入成员',actor_id:'操作人',source_member_id:'来源成员',candidate_umi:'计算收益 UMI',cap_before_umi:'额度变化前',cap_after_umi:'额度变化后',deposit_id:'充值凭证 ID',custody_transfer_id:'托管任务 ID',locked_shares:'锁定份额',available_shares:'可转份额',asset:'资产',price:'价格',observed_at:'报价时点',source_ref:'来源编号',quote_source:'报价来源',quote_at:'报价时点',umi_usd_quote:'UMI 报价',approved_by:'核定人',static_rate:'静态日率',summary_json:'结算摘要',before_json:'变更前',after_json:'变更后',basis:'开通依据',burn_evidence_id:'销毁凭证 ID',pending_before_umi:'待划转余额变更前',pending_after_umi:'待划转余额变更后',available_before_umi:'可提余额变更前',available_after_umi:'可提余额变更后'};
export default {mixins:[UmiLocale],props:{adminView:Boolean,allowExport:{type:Boolean,default:false},initialDataset:{type:String,default:'withdrawals'}},data(){const q=new URLSearchParams(window.location.search);return {dataset:q.get('record_dataset')||this.initialDataset,withdrawalId:q.get('record_withdrawal')||'',memberId:q.get('record_member')||'',rootId:q.get('record_root')||'',search:q.get('record_search')||'',from:q.get('record_from')||'',to:q.get('record_to')||'',status:q.get('record_status')||'',source:q.get('record_source')||'',page:Number(q.get('record_page'))||1,result:null,error:'',loading:false,expanded:null,sequence:0};},computed:{datasets(){return Object.fromEntries(Object.entries(names).filter(([k])=>this.adminView||!['members','stock_accounts','quotes','daily','settings','activation','recovery','recovery_actions','ranks'].includes(k)));},supportsMember(){return !['quotes','daily','settings','recovery_actions'].includes(this.dataset);},endpoint(){return this.adminView?'/exchange-control-panel/umi/operations/records':'/umi-ecosystem/portfolio/records';},visibleColumns(){const c=this.result?.columns||[];return c.filter(k=>!['policy_version_id','legacy_identity_ref'].includes(k)).slice(0,7);},exportUrl(){return this.endpoint+'?'+new URLSearchParams({...this.params(),format:'csv'});}},mounted(){if(!this.datasets[this.dataset])this.dataset=this.initialDataset;this.load(this.page,'replace');window.addEventListener('popstate',this.restoreUrl);},beforeDestroy(){window.removeEventListener('popstate',this.restoreUrl);},methods:{restoreUrl(){const q=new URLSearchParams(window.location.search);const keys={dataset:'dataset',memberId:'member',rootId:'root',search:'search',from:'from',to:'to',status:'status',source:'source',withdrawalId:'withdrawal'};Object.entries(keys).forEach(([field,key])=>this[field]=q.get('record_'+key)||'');if(!this.datasets[this.dataset])this.dataset=this.initialDataset;this.load(Number(q.get('record_page'))||1,'none');},fmt:formatUmi,time:umiTime,statusLabel:umiStatus,label(k){return labels[k]||k;},display(v,k){if(v===null||v===undefined)return '—';if(['status','source','kind','pocket','purpose','term_status'].includes(k))return umiStatus(v);if(['from_bucket','to_bucket'].includes(k))return {trade:'现货账户',wallet:'资金账户'}[v]||v;if(k.endsWith('_at'))return umiTime(v);return typeof v==='object'?JSON.stringify(v):(/(?:_umi|_usd|_shares|_points)$/.test(k)||['shares','price','umi_usd_quote','static_rate'].includes(k)?formatUmi(v):String(v));},params(){const f={dataset:this.dataset,status:this.status,source:this.source,date_from:this.from,date_to:this.to};if(this.adminView&&this.supportsMember){f.member_id=this.memberId;f.root_member_id=this.rootId;}if(this.dataset==='members')f.search=this.search;if(['withdrawals','lots','points'].includes(this.dataset))f.withdrawal_id=this.withdrawalId;return Object.fromEntries(Object.entries(f).filter(([,v])=>v!==''&&v!==null));},async load(page=1,historyMode='push'){const sequence=++this.sequence;this.loading=true;this.error='';this.expanded=null;try{const r=await axios.get(this.endpoint,{params:{...this.params(),page}});if(sequence!==this.sequence)return;this.result=r.data;this.page=page;const u=new URL(window.location.href);const f={dataset:this.dataset,member:this.memberId,root:this.rootId,search:this.search,from:this.from,to:this.to,status:this.status,source:this.source,page,withdrawal:this.withdrawalId};Object.entries(f).forEach(([k,v])=>v?u.searchParams.set('record_'+k,v):u.searchParams.delete('record_'+k));if(historyMode!=='none')window.history[historyMode==='replace'?'replaceState':'pushState']({},'',u.toString());}catch(e){if(sequence===this.sequence)this.error=Object.values(e.response?.data?.errors||{}).flat().join('；')||e.response?.data?.message||'查询失败，请重试。';}finally{if(sequence===this.sequence)this.loading=false;}},changeDataset(){this.withdrawalId='';this.status='';this.source='';this.result=null;this.load(1);},reset(){this.withdrawalId='';this.memberId='';this.rootId='';this.search='';this.from='';this.to='';this.status='';this.source='';this.load(1);}}};
</script>
<style scoped>
.ur{background:#fff;border:1px solid #dfe9e1;border-radius:18px;padding:22px;margin:18px 0;color:#203a2a}.ur header{display:flex;justify-content:space-between;align-items:start;gap:15px}.ur h2{font-size:21px;margin:0 0 8px}.ur p,.ur small{color:#667a6c}.ur a{color:#17813d}.ur-filters{display:flex;flex-wrap:wrap;align-items:end;gap:12px;margin:18px 0}.ur label{font-size:12px}.ur input,.ur select{display:block;padding:9px;border:1px solid #cbdacf;border-radius:8px;margin-top:5px;max-width:190px;background:transparent;color:inherit}.ur button{border:1px solid #bdd3c5;border-radius:8px;padding:8px 12px;background:#eef8f1;color:#22643a;cursor:pointer}.ur button:disabled{opacity:.45;cursor:default}.ur-summary{display:flex;flex-wrap:wrap;gap:12px;padding:14px;background:#f0f8f3;border-radius:10px;font-size:13px}.ur-scroll{overflow:auto}.ur table{border-collapse:collapse;width:100%;font-size:13px;margin-top:15px}.ur th,.ur td{padding:12px;border-bottom:1px solid #e6eee9;text-align:left;white-space:nowrap}.ur dl{display:grid;grid-template-columns:minmax(120px,1fr) minmax(0,4fr);gap:10px;white-space:normal}.ur dd{margin:0;overflow-wrap:anywhere}.ur dt{color:#657b6d}.ur footer{display:flex;justify-content:space-between;align-items:center;margin:18px 0}.ur-error{color:#a02b2b}.ur input:focus,.ur select:focus{outline:2px solid #e9ba17}body.dark .ur{background:#202a24;color:#edf3ee;border-color:#3c4a40}body.dark .ur-summary,body.dark .ur button{background:#2a3b30;color:#c9e9d4}body.dark .ur a{color:#80d69a}body.dark .ur p,body.dark .ur small{color:#b6c6ba}@media(max-width:650px){.ur{padding:15px}.ur header{display:block}.ur-filters label{width:calc(50% - 7px)}.ur input,.ur select{width:100%;max-width:100%;box-sizing:border-box}.ur dl{grid-template-columns:100px minmax(0,1fr)}}
</style>
